use super::*;
fn base()->Params{Params::defaults(&params())}
#[test]fn arithmetic_hand_checks(){let p=base();let v=numbers(&p,&mut vec![]);for(m,a,b)in[("Sum",2.,3.),("Difference",4.,1.),("Product",-5.,1.),("Quotient",-0.5,-2.5),("Conjugate",3.,-2.)]{let t=op(&v[0],&v[1],m).unwrap();assert!((t.a.v-a).abs()<1e-12&& (t.b.v-b).abs()<1e-12,"{m}");}assert_eq!(modtext(&v[0],&p),"√13");}
#[test]fn principal_angles(){for(a,b,want)in[(1,1,"π/4"),(-1,1,"3π/4"),(-1,-1,"−3π/4"),(1,-1,"−π/4"),(0,1,"π/2"),(-1,0,"π")]{let z=Z{a:from_q(Q(a,1)),b:from_q(Q(b,1)),name:"z".into()};assert_eq!(angtext(&z,&base()),want);}}
#[test]fn roots_and_powers_independent(){let mut p=base();p.set_s("zr","8");p.set_s("zi","0");p.set_s("operation","Roots");let(v,n)=all(&p,&mut vec![]);let expected=[(2.,0.),(-1.,3f64.sqrt()),(-1.,-3f64.sqrt())];for(z,(a,b))in v[n..].iter().zip(expected){assert!((z.a.v-a).abs()<1e-12);assert!((z.b.v-b).abs()<1e-12);}p.set_s("operation","Powers");p.set_s("zr","1");p.set_s("zi","1");let(v,n)=all(&p,&mut vec![]);assert_eq!(v[n].xy(),(0.,2.));assert_eq!(v[n+1].xy(),(-2.,2.));}
#[test]fn student_does_not_leak(){let mut p=base();p.set_b(SHOW_ANSWERS,false);p.set_s("question","Coordinates");let s=render(&p);assert!(!s.contains("√13"));assert!(!s.contains("3 + 2i"));p.set_s("question","Construction");let s=render(&p);assert!(!s.contains("2 + 3i"));assert!(!s.contains("data-lbl=\"p2\""));}
#[test]fn sweep(){let start=std::time::Instant::now();let mut count=0;for size in ["Small","Medium","Large"]{for a in -5..=4{for b in [-3,-1,1,3,5,0]{for operation in ["None","Conjugate","Sum","Difference","Product","Quotient","Roots","Powers"]{let mut p=base();p.set_s("zr",&a.to_string());p.set_s("zi",&b.to_string());p.set_s("label_size",size);p.set_s("operation",operation);let s=render(&p);assert_eq!(s,render(&p));assert!(!s.contains("NaN"));assert!(s.len()<100000);count+=1;}}}}eprintln!("{count} deterministic renders in {:?}",start.elapsed());}
#[test]fn rational_and_invalid(){assert_eq!(read("1/3").unwrap().s,"1/3");assert_eq!(read("0.50").unwrap().s,"0.50");assert_eq!(read("1e-5").unwrap().v,0.00001);assert_eq!(read("sqrt(13)").unwrap().s,"√13");assert!(!read("2*3").unwrap().exact);let mut p=base();p.set_s("wr","0");p.set_s("wi","0");p.set_s("operation","Quotient");assert!(warnings(&p).iter().any(|x|x.contains("zero")));}
#[test]fn pngs(){let Ok(dir)=std::env::var("VERSHION_PNG_DIR")else{return};for(tag,mode,style,key)in[("colour","Construction","Colour",true),("student","Coordinates","Colour",false),("key","Coordinates","Colour",true),("print","Construction","Print",true)]{let mut p=base();p.set_s("question",mode);p.set_s("style",style);p.set_b(SHOW_ANSWERS,key);std::fs::write(format!("{dir}/{tag}.png"),to_png(&render(&p),1.).unwrap()).unwrap();}}
